/* Original concise teaching notes. Curriculum coverage is a study outline, not a substitute for the NMC competency document or a textbook. */
const SUBJECTS = [
{id:'anatomy',name:'Anatomy',phase:'Pre-clinical',tagline:'Meet the architecture of the human body.',color:'#e7efe3',ink:'#426440',cover:'Structure makes sense.',flow:['Cells','Tissues','Organs'],scope:'General anatomy; upper and lower limbs; thorax; abdomen; pelvis and perineum; head and neck; neuroanatomy; embryology; histology; genetics; surface and radiological anatomy',units:`
Body organization & tissue types~Think of the body as a city: cells are residents, tissues are teams, and organs are workplaces.~Epithelia cover surfaces and form glands; connective tissues support and bind structures.|Muscle generates force; nervous tissue receives and transmits information.|Anatomical position standardizes directions: medial is toward the midline, proximal is nearer a limb attachment.~Which tissue covers surfaces and forms glands?~Epithelium~Cell>Tissue>Organ
Upper limb & peripheral nerves~A nerve is a cable carrying instructions to muscles and information back from skin.~The brachial plexus usually comes from C5–T1 and reorganizes into terminal nerves.|The radial nerve supports extension; the median nerve supplies most forearm flexors and thenar function; the ulnar nerve supplies many intrinsic hand muscles.|Localize an injury using the pattern of weakness and sensory loss, rather than one symptom alone.~Which nerve is classically associated with wrist drop?~Radial nerve~Roots>Plexus>Peripheral nerve
Lower limb & locomotion~Walking depends on joints acting as hinges and muscles pulling across them.~The femoral nerve supplies the quadriceps, which extend the knee.|The sciatic nerve divides into tibial and common fibular components; common fibular injury may cause foot drop.|Hip abductors stabilize the pelvis during single-leg stance; their major nerve supply is the superior gluteal nerve.~Which muscle group extends the knee?~Quadriceps~Pelvic stability>Joint movement>Gait
Thorax, abdomen & pelvis~Body cavities contain organs with specific neighbors; those relationships explain many symptoms and procedures.~The right heart sends blood to the lungs; the left heart sends blood to the body.|The portal vein carries nutrient-rich blood from much of the digestive tract to the liver.|The ureter passes beneath the uterine artery; pelvic relationships matter during surgery.~Which vessel carries intestinal blood to the liver?~Portal vein~Digestive organs>Portal vein>Liver
Head, neck & neuroanatomy~The nervous system is a communication network with routes that can be mapped.~Cranial nerves have specific sensory, motor and autonomic functions; learn each through an examination finding.|The corticospinal tract carries voluntary motor commands; many fibers cross in the lower medulla.|CSF circulates through ventricles and the subarachnoid space; obstruction can enlarge upstream ventricles.~Where do most corticospinal fibers cross?~Lower medulla~Motor cortex>Corticospinal tract>Muscle
Embryology, histology & genetics~Development explains why structures exist where they do and why congenital differences occur.~Ectoderm forms epidermis and much of the nervous system; mesoderm forms muscle and connective tissues; endoderm forms much of the gut lining.|Neural tube closure is an early developmental event; folate is important to prevention of some neural tube defects.|In histology, identify the tissue pattern first, then cells, then organ-specific features.~Which germ layer forms much of the nervous system?~Ectoderm~Germ layers>Tissue differentiation>Organs`},
{id:'physiology',name:'Physiology',phase:'Pre-clinical',tagline:'Understand how a healthy body actually works.',color:'#e5edf5',ink:'#3b5c79',cover:'Every system, connected.',flow:['Stimulus','Response','Balance'],scope:'Cell physiology; nerve and muscle; blood; cardiovascular and respiratory systems; renal and acid–base physiology; gastrointestinal physiology; endocrine and reproductive systems; CNS and special senses',units:`
Homeostasis, cells & membranes~Your body adjusts continuously, much like a thermostat maintaining a room temperature.~Negative feedback opposes a change; positive feedback amplifies a change until an endpoint.|Diffusion follows a concentration gradient; active transport requires energy directly or indirectly.|The sodium–potassium pump helps maintain ion gradients, which support membrane potential and transport.~Which feedback type opposes a disturbance?~Negative feedback~Change>Sensor>Corrective response
Nerve, muscle & special senses~Electrical changes carry messages, and muscle cells turn signals into movement.~An action potential involves voltage-gated ion channels and an all-or-none response in a single excitable fiber.|At the neuromuscular junction, acetylcholine activates nicotinic receptors.|Calcium permits actin–myosin interaction; skeletal muscle uses troponin, while smooth muscle relies on calmodulin signaling.~Which transmitter acts at the skeletal neuromuscular junction?~Acetylcholine~Nerve signal>Calcium release>Contraction
Blood & cardiovascular physiology~The heart is a pump; blood vessels distribute flow to match tissue needs.~Cardiac output equals heart rate multiplied by stroke volume.|Mean arterial pressure is approximately cardiac output multiplied by systemic vascular resistance when central venous pressure is small.|Hemoglobin transports most oxygen; platelets and clotting factors work together in hemostasis.~What is cardiac output equal to?~Heart rate × stroke volume~Heart rate + stroke volume>Cardiac output>Tissue flow
Respiration & gas exchange~Breathing moves air; gas exchange moves oxygen and carbon dioxide between air and blood.~Ventilation is air movement; perfusion is blood flow through pulmonary capillaries.|Gas diffuses across the alveolar membrane according to gradients and membrane properties.|A ventilation–perfusion mismatch can impair oxygenation even when air is entering the lungs.~What does pulmonary perfusion mean?~Blood flow through lung capillaries~Ventilation>Alveolar exchange>Blood oxygenation
Kidney, fluids & acid–base~Kidneys act as adjustable filters that retain useful substances and remove waste.~Filtration moves plasma water and small solutes into the nephron; reabsorption returns substances to blood; secretion moves substances into tubular fluid.|ADH increases collecting-duct water permeability; aldosterone promotes sodium retention and potassium secretion.|Lungs alter carbon dioxide quickly; kidneys adjust bicarbonate and acid excretion over longer times.~Which hormone increases collecting-duct water permeability?~ADH~Filtration>Tubular adjustment>Urine
GI, endocrine & reproduction~Digestion supplies fuel; hormones coordinate how the body uses it and reproduces.~Insulin favors nutrient storage and lowers circulating glucose through several mechanisms.|Thyroid hormones influence metabolism; pituitary and hypothalamic signals regulate many endocrine axes.|Gonadotropins regulate ovarian and testicular function; feedback varies through the menstrual cycle.~Which hormone generally promotes nutrient storage after a meal?~Insulin~Hormone signal>Target receptor>Cell response`},
{id:'biochemistry',name:'Biochemistry',phase:'Pre-clinical',tagline:'Make the molecules behind medicine click.',color:'#f4eddb',ink:'#856a2e',cover:'Small molecules. Big ideas.',flow:['Fuel','Pathway','Energy'],scope:'Proteins and enzymes; carbohydrate, lipid and amino-acid metabolism; vitamins and minerals; molecular biology; genetics; nutrition; acid–base chemistry; clinical biochemistry and inborn errors',units:`
Proteins, enzymes & kinetics~Enzymes are biological helpers that speed reactions without being used up.~Protein shape supports function; changing shape can change activity.|Km is the substrate concentration at half maximal velocity in Michaelis–Menten kinetics.|A competitive inhibitor raises apparent Km without changing Vmax in the ideal model.~What happens to Vmax in ideal competitive inhibition?~It remains unchanged~Substrate>Enzyme complex>Product
Carbohydrate metabolism~Cells process sugar through connected pathways to obtain energy or store fuel.~Glycolysis occurs in the cytosol and converts glucose to pyruvate.|The citric acid cycle and oxidative phosphorylation link fuel oxidation to ATP generation.|Glycogenesis stores glucose as glycogen; gluconeogenesis makes glucose from non-carbohydrate precursors.~Where does glycolysis occur?~Cytosol~Glucose>Pyruvate>ATP generation
Lipids & lipoproteins~Fat is concentrated fuel; transport particles move it through watery blood.~Beta-oxidation breaks fatty acids into acetyl-CoA units.|Chylomicrons transport dietary lipids; VLDL carries many liver-derived triglycerides.|LDL participates in cholesterol delivery; HDL participates in reverse cholesterol transport, but risk cannot be reduced to one isolated value.~Which particles transport dietary triglycerides from the intestine?~Chylomicrons~Dietary fat>Transport particles>Tissue uptake
Amino acids, urea & inborn errors~Protein breakdown produces nitrogen waste that must be handled safely.~Transamination transfers amino groups; the urea cycle converts toxic nitrogen into urea, mainly in the liver.|Phenylketonuria is commonly associated with impaired phenylalanine hydroxylation.|A pathway block may increase upstream metabolites and reduce downstream products; use that logic for inherited disorders.~Which pathway converts nitrogen into urea?~Urea cycle~Amino nitrogen>Urea cycle>Renal excretion
Vitamins, minerals & nutrition~Micronutrients help enzymes work even though the body needs only small amounts.~Vitamin B1 supports several energy-metabolism enzymes; B12 and folate support DNA synthesis.|Vitamin C supports collagen-related reactions; vitamin D supports calcium and phosphate homeostasis.|Fat-soluble vitamins are A, D, E and K; both deficiency and excess can be harmful.~Which vitamins are fat-soluble?~A, D, E and K~Nutrient intake>Absorption>Cell function
DNA, RNA & laboratory interpretation~DNA is stored information; RNA helps cells use it to make proteins.~Replication copies DNA, transcription makes RNA, and translation makes protein.|PCR amplifies selected DNA sequences; molecular tests answer specific questions rather than detecting every disease.|Interpret laboratory values with units, reference intervals, specimen conditions and clinical context.~What is transcription?~Making RNA from a DNA template~DNA>RNA>Protein`},
{id:'pathology',name:'Pathology',phase:'Para-clinical',tagline:'Follow the story from normal cells to disease.',color:'#f2e6e8',ink:'#8a5261',cover:'Understand what changes.',flow:['Injury','Response','Disease'],scope:'Cell injury and adaptation; inflammation and repair; immunopathology; neoplasia; hemodynamics; hematology; cardiovascular, respiratory, renal, GI, hepatic, endocrine, reproductive and nervous-system pathology',units:`
Cell injury, adaptation & death~Cells can adapt to stress, recover from injury, or die when damage is too severe.~Hypertrophy increases cell size; hyperplasia increases cell number; metaplasia replaces one differentiated cell type with another.|Necrosis commonly provokes inflammation; apoptosis is regulated cell death with limited surrounding inflammation.|Reversible and irreversible injury depend on the nature, duration and severity of the insult.~What does hypertrophy mean?~An increase in cell size~Stress>Adaptation or injury>Recovery or death
Inflammation & repair~Inflammation recruits defenses; repair rebuilds tissue but may leave a scar.~Acute inflammation often features vascular changes and neutrophils; chronic inflammation commonly involves mononuclear cells.|Granulomas are organized collections of activated macrophages and occur in infectious and noninfectious conditions.|Healing depends on tissue regenerative capacity, blood supply, infection and other factors.~Which cells often dominate early acute inflammation?~Neutrophils~Injury>Inflammation>Repair
Hemodynamics & immunopathology~Problems with flow or immune recognition can injure otherwise normal tissue.~Thrombosis is clot formation within the circulation; embolism is traveling material that obstructs a vessel.|Virchow's triad comprises endothelial injury, abnormal flow and hypercoagulability.|Hypersensitivity mechanisms are grouped as types I–IV; type IV is primarily T-cell mediated.~Which hypersensitivity type is primarily T-cell mediated?~Type IV~Trigger>Immune or vascular response>Tissue injury
Neoplasia & tumor biology~Cancer involves uncontrolled growth plus the ability of malignant cells to invade.~Benign tumors do not metastasize; malignant tumors may invade and spread.|Oncogenes promote growth when activated; tumor suppressor loss removes restraints.|Grade describes differentiation and related features; stage describes extent of spread and often strongly informs prognosis.~What does tumor stage describe?~Extent of disease spread~Genetic change>Clonal growth>Invasion or spread
Anemia, leukemia & hemostasis~Blood diseases may affect oxygen transport, infection defense or clotting.~Classify anemia by cell size, reticulocyte response and mechanism, rather than hemoglobin alone.|Iron deficiency commonly causes microcytosis; B12 or folate deficiency can cause megaloblastic change.|Leukemia is a clonal hematologic malignancy; platelet problems often cause mucocutaneous bleeding, while factor defects may cause deeper bleeding.~Which deficiency commonly causes microcytic anemia?~Iron deficiency~Blood count>Cell pattern>Mechanism
Systemic pathology~A disease pattern becomes easier to remember when linked to the organ's normal job.~Atherosclerosis involves intimal lipid accumulation and inflammation; ischemia can lead to infarction.|Nephritic patterns emphasize glomerular inflammation and hematuria; nephrotic patterns emphasize heavy protein loss.|Cirrhosis combines fibrosis and regenerative nodules, disrupting liver architecture and flow.~Which renal pattern emphasizes heavy protein loss?~Nephrotic pattern~Organ injury>Structural change>Functional loss`},
{id:'pharmacology',name:'Pharmacology',phase:'Para-clinical',tagline:'Connect every drug class to its mechanism.',color:'#e4efed',ink:'#356f68',cover:'Mechanism before memory.',flow:['Drug','Receptor','Response'],scope:'General pharmacology; autonomic and CNS drugs; cardiovascular and renal drugs; autacoids; endocrine agents; antimicrobials; chemotherapy; GI and respiratory drugs; adverse reactions and rational prescribing',units:`
Pharmacokinetics & pharmacodynamics~Pharmacokinetics asks what the body does to a drug; pharmacodynamics asks what a drug does to the body.~Absorption, distribution, metabolism and excretion determine drug exposure.|Clearance relates elimination rate to concentration; half-life depends on clearance and volume of distribution in a simple first-order model.|Potency and efficacy are different: needing a smaller dose does not imply a larger maximum effect.~Which term describes the maximum effect of a drug?~Efficacy~Dose>Drug exposure>Effect
Autonomic pharmacology~Drugs can imitate or block the body's automatic signaling systems.~Muscarinic receptors mediate many parasympathetic effects; nicotinic receptors occur in ganglia and neuromuscular junctions.|Beta-1 stimulation supports cardiac activity; beta-2 stimulation can relax bronchial smooth muscle.|Receptor selectivity is relative and may diminish at higher exposure.~Which receptor commonly mediates bronchodilation?~Beta-2 receptor~Receptor binding>Signal change>Organ response
Cardiovascular & renal drugs~These drugs alter pumping, vessel tone, fluid balance or clotting.~ACE inhibitors reduce angiotensin II formation and affect bradykinin metabolism.|Loop diuretics inhibit the Na-K-2Cl transporter in the thick ascending limb.|Antiplatelets and anticoagulants act on different components of thrombosis and are not interchangeable.~Where do loop diuretics act?~Thick ascending limb~Drug target>Physiological change>Clinical effect
CNS, pain & anesthesia drugs~Changing chemical signaling in the nervous system can alter mood, pain, seizures or consciousness.~Benzodiazepines enhance GABA-A receptor activity; opioids act at opioid receptors.|NSAIDs reduce prostaglandin synthesis through cyclooxygenase inhibition.|Benefit and adverse effects depend on the drug, dose, comorbidity and interactions; mechanisms do not replace prescribing guidance.~Which enzymes are inhibited by NSAIDs?~Cyclooxygenase enzymes~Neural target>Signal modulation>Symptom change
Antimicrobials & chemotherapy~Antimicrobials exploit differences between microbes and human cells.~Beta-lactams inhibit bacterial cell-wall synthesis; macrolides inhibit bacterial protein synthesis.|Resistance can involve target modification, drug destruction, reduced entry or increased efflux.|Antimicrobial selection depends on organism, site, susceptibility, patient factors and stewardship; antibiotics do not treat viral infections routinely.~What is the main bacterial target of beta-lactams?~Cell-wall synthesis~Microbial target>Growth inhibition>Host recovery
Endocrine, GI & respiratory drugs~The same receptor-and-pathway logic organizes drugs across organ systems.~Insulin therapy replaces or supplements insulin action; other glucose-lowering classes act through different mechanisms.|Proton-pump inhibitors suppress gastric acid by inhibiting the parietal-cell proton pump.|Inhaled corticosteroids reduce airway inflammation; bronchodilators primarily affect airway caliber.~Which drug class inhibits the gastric proton pump?~Proton-pump inhibitors~Pathway target>Functional change>Monitor benefit and harm`},
{id:'microbiology',name:'Microbiology',phase:'Para-clinical',tagline:'Learn the organisms and the defenses they meet.',color:'#eee8f4',ink:'#70548e',cover:'A world beneath the lens.',flow:['Microbe','Host','Defense'],scope:'General microbiology; immunology; bacteriology; virology; mycology; parasitology; sterilization and disinfection; diagnostic methods; infection prevention; antimicrobial resistance',units:`
Microbial foundations & diagnostics~Different microbes need different detection methods because their structures and behavior differ.~Bacteria are cells; viruses depend on host cellular machinery for replication.|Gram staining reflects cell-wall properties but does not identify every organism.|Culture, antigen tests, microscopy and nucleic-acid tests have different strengths and limitations.~Which organisms require host cells for replication?~Viruses~Specimen>Suitable test>Interpretation
Immunology & host defense~Innate immunity reacts quickly; adaptive immunity develops targeted recognition and memory.~Physical barriers, phagocytes and complement contribute to innate defense.|B cells produce antibodies; T cells support immune coordination and cell-mediated responses.|Vaccination aims to establish protective immune memory without the risks of the natural infection.~Which cells differentiate into antibody-secreting plasma cells?~B cells~Antigen recognition>Immune activation>Memory
Bacteriology~Classify bacteria by structure, oxygen needs and clinical pattern before memorizing names.~Staphylococci often form clusters; streptococci often form chains or pairs.|Mycobacteria have lipid-rich cell walls and may be demonstrated using acid-fast methods.|Toxin-mediated illness and invasive infection can produce different patterns; laboratory confirmation matters.~Which staining property is associated with mycobacteria?~Acid-fastness~Bacterial entry>Virulence mechanisms>Host response
Virology~A virus carries genetic instructions and uses a host cell to reproduce.~Viral genomes may be DNA or RNA; replication strategies vary.|Latency and persistent infection differ from a short, self-limited acute infection.|Viral diagnosis depends on timing: nucleic acid, antigen and antibody tests may answer different questions.~What does viral latency mean?~Persistence with limited activity and possible reactivation~Entry>Replication>Release
Mycology & parasitology~Fungi and parasites are distinct groups with different structures and life cycles.~Fungi may grow as yeasts, molds or different forms depending on conditions.|Parasite life cycles may include intermediate hosts, vectors and tissue stages.|For malaria, species identification and parasite burden matter; prevention includes vector control and context-specific measures.~What is a vector?~An organism that transmits a pathogen~Reservoir or vector>Human host>Life-cycle stage
Sterilization, infection control & resistance~Preventing transmission protects patients before a treatment is needed.~Sterilization aims to eliminate all microbial life including spores; disinfection is not always sporicidal.|Hand hygiene, appropriate precautions and safe equipment processing reduce healthcare-associated infection.|Resistance is selected under antimicrobial pressure; susceptibility results must be interpreted using validated laboratory standards.~Which process includes elimination of bacterial spores?~Sterilization~Source control>Transmission interruption>Protected host`},
{id:'forensic',name:'Forensic Medicine',phase:'Para-clinical',tagline:'Connect medicine, evidence and professional ethics.',color:'#e9eaf0',ink:'#535c78',cover:'Observe. Document. Explain.',flow:['Finding','Evidence','Opinion'],scope:'Medical ethics and law; consent and confidentiality; death and postmortem changes; identification; injuries; asphyxia; toxicology; sexual offences; medico-legal documentation',units:`
Ethics, consent & confidentiality~Good medical practice respects autonomy, welfare, fairness and privacy.~Valid consent requires capacity, adequate information and voluntariness; requirements depend on the procedure and jurisdiction.|Confidentiality has defined legal and professional exceptions, not unlimited discretion.|Document facts, decisions and discussions clearly; use current Indian legal and regulatory sources for exam-specific provisions.~What is voluntariness in consent?~A decision free from coercion~Information>Understanding>Voluntary decision
Identification & evidence~Forensic conclusions are strongest when multiple independent findings agree.~Identification may use fingerprints, dental evidence, DNA and contextual findings.|Maintain chain of custody to document who handled a specimen and when.|An observation is not the same as an inference; report the basis and limitations of each opinion.~What records the handling history of evidence?~Chain of custody~Collection>Documentation>Analysis
Death & postmortem changes~Changes after death provide clues, but environmental conditions affect their timing.~Algor, livor and rigor mortis describe cooling, dependent discoloration and stiffening.|Decomposition depends on temperature, environment and other factors.|Do not infer an exact time of death from one isolated postmortem sign.~Which term describes postmortem stiffening?~Rigor mortis~Death>Early changes>Decomposition
Mechanical injuries~Describe an injury before assigning a cause.~Abrasions involve superficial skin loss; contusions involve bleeding into tissue; lacerations are tears.|Incised wounds generally have clean margins from a sharp edge, but interpretation depends on the whole case.|Document dimensions, location, appearance and relevant photographs according to protocol.~What is a contusion?~Bleeding into tissue caused by blunt injury~Force>Tissue damage>Observed wound
Asphyxia & environmental injury~Oxygen delivery can fail through several mechanisms, not only airway blockage.~Asphyxial circumstances require integration of scene, history, examination and investigations.|Classical signs such as petechiae are not specific by themselves.|Heat, cold, electricity and drowning require mechanism-specific assessment and careful exclusion of alternatives.~Are petechiae alone diagnostic of a specific asphyxial cause?~No, they are nonspecific~Exposure>Physiological disruption>Injury
Toxicology~Toxicity depends on substance, amount, route, timing and patient factors.~Toxidromes group clinical signs that can suggest a class of poison.|Organophosphates inhibit acetylcholinesterase, producing cholinergic effects.|Poison management is an emergency clinical task; laboratory results and antidote decisions require professional protocols.~Which enzyme is inhibited by organophosphates?~Acetylcholinesterase~Exposure>Absorption>Toxic effect`},
{id:'community',name:'Community Medicine',phase:'Clinical',tagline:'Zoom out from one patient to a whole population.',color:'#e7f0df',ink:'#536e3a',cover:'Health, at every scale.',flow:['Population','Evidence','Prevention'],scope:'Epidemiology; biostatistics; screening; communicable and noncommunicable disease control; demography; maternal and child health; nutrition; environment; occupational health; health systems and national programmes',units:`
Epidemiology & study design~Epidemiology studies how disease is distributed and why it occurs.~Incidence counts new cases over a defined time; prevalence measures existing cases in a population.|Cohort studies follow exposure toward outcomes; case-control studies compare past exposure in cases and controls.|Association alone does not prove causation; confounding, bias and chance need consideration.~Which measure describes existing cases in a population?~Prevalence~Question>Study design>Inference
Biostatistics & interpretation~Statistics helps distinguish a real pattern from random variation.~A mean is sensitive to extreme values; a median is more resistant.|Confidence intervals communicate estimate precision under a statistical model.|A small p-value is not the probability that a hypothesis is true and does not measure clinical importance.~Which measure of central tendency is less sensitive to extreme values?~Median~Data>Estimate>Uncertainty
Screening & diagnostic tests~A screening test looks for possible disease before it is clinically apparent.~Sensitivity is the proportion of diseased people who test positive; specificity is the proportion of nondiseased people who test negative.|Predictive values depend on prevalence and test performance.|Screening benefits must be balanced against false positives, overdiagnosis and harms.~What does sensitivity measure?~The proportion of diseased people testing positive~Eligible population>Screening>Confirmatory assessment
Disease control & prevention~Prevention can act before disease starts, detect it early or reduce its consequences.~Primary prevention reduces disease occurrence; secondary prevention detects and treats early disease.|Tertiary prevention limits disability and supports rehabilitation.|Control programmes and immunization schedules change; verify current recommendations in official programme guidance.~Which prevention level includes rehabilitation?~Tertiary prevention~Risk reduction>Early detection>Disability limitation
Maternal-child health, nutrition & demography~Population health changes with births, deaths, migration and access to care.~Rates and ratios need correct numerators, denominators and time periods.|Maternal and child indicators identify gaps in prevention, timely care and social conditions.|Assess nutrition using dietary, clinical, anthropometric and biochemical information as appropriate.~What must accompany a health rate for meaningful interpretation?~A defined denominator and time period~Population data>Health indicators>Service planning
Environment, work & health systems~Clean water, safe work and accessible services influence health beyond the clinic.~Safe water systems combine source protection, treatment and distribution safeguards.|Occupational health focuses on exposure identification and a hierarchy of controls.|Primary healthcare includes promotion, prevention, treatment and continuity; local referral systems connect levels of care.~What is the first aim of occupational hazard control?~Eliminate or reduce the exposure~Hazard>Exposure control>Health protection`},
{id:'medicine',name:'General Medicine',phase:'Clinical',tagline:'Turn mechanisms into clinical reasoning.',color:'#e1eeee',ink:'#35666b',cover:'See the whole patient.',flow:['Symptoms','Mechanism','Diagnosis'],scope:'Cardiology; pulmonology; gastroenterology and hepatology; nephrology; endocrinology; neurology; hematology; rheumatology; infectious disease; emergencies; geriatrics',units:`
Clinical reasoning & emergencies~A diagnosis is a reasoned explanation of the history, examination and investigations.~First identify threats to airway, breathing and circulation; urgent stabilization and diagnostic work often proceed together.|Shock is inadequate tissue perfusion and may be hypovolemic, cardiogenic, distributive or obstructive.|A differential diagnosis is a prioritized list, not an indiscriminate collection of diseases.~What is the core physiological problem in shock?~Inadequate tissue perfusion~Presentation>Prioritized assessment>Working diagnosis
Cardiology & vascular medicine~Heart disease may affect supply, pumping, valves, rhythm or the surrounding structures.~Myocardial ischemia reflects inadequate oxygen supply relative to demand.|Heart failure is a clinical syndrome caused by structural or functional cardiac abnormalities; ejection fraction alone does not exclude it.|An ECG is interpreted systematically for rate, rhythm, axis, intervals and waveform changes.~Can preserved ejection fraction exclude heart failure?~No~Cardiac problem>Hemodynamic effect>Clinical findings
Respiratory medicine~Breathlessness can come from lungs, heart, blood or metabolic disturbances.~Obstructive disorders limit expiratory airflow; restrictive patterns reduce lung volumes.|Asthma involves variable airflow limitation and airway inflammation; COPD often has persistent airflow limitation.|Tuberculosis assessment integrates symptoms, imaging and appropriate microbiological testing.~Which physiological pattern limits expiratory airflow?~Obstructive pattern~Airway or lung change>Gas-exchange effect>Breathlessness
GI, liver & kidney medicine~Interpret organ dysfunction by asking what is failing: processing, flow, filtration or excretion.~Jaundice reflects bilirubin accumulation; prehepatic, hepatic and posthepatic causes differ.|Acute kidney injury is an abrupt decline in kidney function; prerenal, intrinsic and postrenal mechanisms organize the differential.|Urinalysis, fluid status and trends in kidney function help interpret a single creatinine value.~Which kidney-injury category includes urinary obstruction?~Postrenal~Underlying cause>Organ dysfunction>Laboratory pattern
Endocrine, hematology & rheumatology~Hormonal, blood and immune disorders often affect many organs at once.~Diabetes involves dysregulated glucose control; type 1 commonly reflects autoimmune beta-cell destruction, while type 2 involves insulin resistance and beta-cell dysfunction.|Anemia needs mechanistic evaluation, including production, loss and destruction.|Inflammatory joint symptoms require differentiation from mechanical pain; systemic autoimmune disease may have extra-articular features.~What are the two key defects in type 2 diabetes?~Insulin resistance and beta-cell dysfunction~Systemic mechanism>Multiple-organ effects>Targeted evaluation
Neurology & infectious disease~Localize neurological problems anatomically, then identify the cause.~A focal deficit suggests a specific pathway or region; abrupt onset may signal a vascular event.|Meningitis and encephalitis differ in predominant meningeal versus brain involvement, although overlap occurs.|Sepsis involves life-threatening organ dysfunction due to a dysregulated response to infection.~What is the defining consequence in sepsis?~Life-threatening organ dysfunction~Infection or lesion>System response>Organ dysfunction`},
{id:'surgery',name:'General Surgery',phase:'Clinical',tagline:'Understand surgical problems from first principles.',color:'#e5ebf3',ink:'#44617d',cover:'Anatomy into action.',flow:['Problem','Assessment','Intervention'],scope:'Wounds; surgical infection; shock, fluids and transfusion; trauma and burns; perioperative care; breast and thyroid; GI and hepatobiliary surgery; hernia; vascular surgery; urology; surgical oncology',units:`
Wounds, infection & perioperative care~Surgical care begins before an operation and continues through recovery.~Assess comorbidities, medications, nutritional status and procedural risk before surgery.|Wound healing has overlapping inflammatory, proliferative and remodeling phases.|Surgical infection prevention combines asepsis, appropriate prophylaxis when indicated and sound perioperative care.~Which phase includes collagen remodeling?~Remodeling phase~Assessment>Procedure>Recovery
Trauma, shock & burns~Trauma care prioritizes immediately life-threatening problems before less urgent injuries.~A structured primary survey identifies threats to airway, breathing and circulation.|Hemorrhage control and appropriate resuscitation are central when blood loss is present.|Burn evaluation considers depth, extent, location, mechanism and inhalation injury, not surface area alone.~What should be prioritized in initial trauma assessment?~Immediate threats to life~Injury>Primary survey>Definitive care
Acute abdomen & intestinal disease~Acute abdominal pain has many causes; pattern and progression help organize them.~Peritonitis can cause guarding and rigidity but signs vary with age and clinical context.|Obstruction may be mechanical or functional; strangulation threatens bowel blood supply.|Appendicitis, perforation and obstruction are examples requiring prompt clinical assessment.~What makes strangulated obstruction especially dangerous?~Compromised bowel blood supply~Obstruction>Distension>Possible ischemia
Hepatobiliary, pancreas & hernia~Flow obstruction explains many biliary problems, while a hernia is protrusion through a weakness.~Gallstones may be asymptomatic or cause inflammation and obstruction depending on location.|Pancreatitis has multiple causes and variable severity; diagnosis uses clinical and investigation criteria.|An incarcerated hernia is irreducible; a strangulated hernia has compromised blood supply.~What distinguishes a strangulated hernia?~Compromised blood supply~Anatomical defect>Protrusion>Possible complication
Breast, thyroid & surgical oncology~A lump needs structured assessment rather than assumptions from feel alone.~Breast evaluation may combine clinical assessment, imaging and tissue sampling where indicated.|Thyroid nodules require evaluation of function and malignancy risk using appropriate tools.|Tumor stage, histology and patient factors guide multidisciplinary management.~What three components often form breast triple assessment?~Clinical examination, imaging and tissue sampling~Lump>Structured evaluation>Diagnosis
Vascular surgery & urology~Blocked flow can affect blood vessels or the urinary tract.~Acute limb ischemia is time-sensitive; pain, pallor, pulse changes and neurological findings may occur.|Urinary retention differs from low urine production; obstruction may occur at several levels.|Hematuria has many causes and needs context-specific evaluation rather than automatic attribution to infection.~How does urinary retention differ from low urine production?~Urine is produced but cannot empty adequately~Flow obstruction>Upstream pressure>Tissue dysfunction`},
{id:'obgyn',name:'Obstetrics & Gynecology',phase:'Clinical',tagline:'Follow reproductive health through every stage.',color:'#f3e7e4',ink:'#925d51',cover:'From cycles to new life.',flow:['Hormones','Cycle','Pregnancy'],scope:'Reproductive physiology; antenatal care; normal and abnormal labor; obstetric emergencies; puerperium; contraception; infertility; menstrual disorders; gynecological infections; benign disease and oncology',units:`
Menstrual cycle & reproductive physiology~The menstrual cycle is coordinated communication between brain, ovaries and uterus.~FSH supports follicular development; an LH surge triggers ovulation.|Estrogen supports endometrial proliferation; progesterone supports secretory transformation.|Cycle length varies; ovulation is not always on day 14 in every person.~Which hormonal surge triggers ovulation?~LH surge~Follicle development>Ovulation>Luteal phase
Antenatal care & normal pregnancy~Pregnancy changes circulation, breathing and metabolism to support fetal development.~Antenatal care assesses maternal health, fetal growth and evolving risks.|Pregnancy dating is more reliable when based on appropriate early information rather than assumptions about cycle timing.|Screening tests estimate risk and may require diagnostic confirmation.~Does a positive screening test always establish a diagnosis?~No, confirmation may be needed~Early assessment>Ongoing monitoring>Birth planning
Labor & intrapartum care~Labor combines uterine contractions, cervical change and fetal descent.~The first stage ends at full cervical dilation; the second ends with birth; the third ends with placental delivery.|Progress and fetal wellbeing are monitored with context-appropriate clinical tools.|A labor abnormality requires assessment of maternal, fetal and mechanical factors.~When does the third stage of labor end?~After delivery of the placenta~Cervical dilation>Birth>Placental delivery
Obstetric emergencies & puerperium~Serious pregnancy complications need rapid specialist assessment.~Preeclampsia is a hypertensive disorder after midpregnancy with proteinuria or other defining organ involvement.|Postpartum hemorrhage causes are often organized as tone, trauma, tissue and thrombin.|The puerperium includes physiological recovery and risks such as infection and thromboembolism.~What are the four Ts of postpartum hemorrhage?~Tone, trauma, tissue and thrombin~Warning sign>Urgent assessment>Cause-directed care
Contraception, infertility & menstrual disorders~Reproductive care is based on goals, physiology and individual circumstances.~Contraceptive methods differ in mechanism, effectiveness, reversibility and suitability.|Infertility evaluation considers both partners and factors including ovulation, tubes and semen.|Abnormal uterine bleeding has structural and nonstructural causes; pregnancy-related causes need consideration when relevant.~Should infertility evaluation consider both partners?~Yes~Patient goals>Evaluation>Shared decisions
Gynecological disease & oncology~Different tissues and organs have distinct patterns of infection, benign growth and cancer.~Fibroids are benign smooth-muscle tumors; endometriosis involves endometrial-like tissue outside the uterus.|Persistent high-risk HPV infection is central to most cervical cancers.|Screening, vaccination and evaluation of symptoms are complementary; screening schedules must follow current local guidance.~Which infection is central to most cervical cancers?~Persistent high-risk HPV infection~Risk factor>Tissue change>Detection and assessment`},
{id:'pediatrics',name:'Pediatrics',phase:'Clinical',tagline:'Learn how medicine changes as children grow.',color:'#f5eedb',ink:'#8a743f',cover:'Small patients. New rules.',flow:['Growth','Development','Health'],scope:'Growth and development; nutrition; neonatology; immunization; infections; pediatric respiratory, cardiac, neurological and renal disease; genetics; emergencies and adolescent health',units:`
Growth & development~Growth describes increasing size; development describes acquiring skills.~Plot serial measurements on appropriate growth charts; the trend matters more than one isolated point.|Milestones occur across motor, language, social and adaptive domains.|Variation exists, but regression of acquired skills deserves careful evaluation.~Which is more informative than a single growth measurement?~Serial growth trend~Measurement>Growth trajectory>Assessment
Nutrition & immunization~Children need enough energy and nutrients for maintenance and growth.~Feeding assessment includes intake, technique, growth and family context.|Undernutrition assessment uses age-appropriate anthropometry and clinical findings.|Immunization schedules and catch-up guidance change; use current official recommendations.~Why are children especially vulnerable to inadequate nutrition?~They need nutrients for growth as well as maintenance~Intake>Growth needs>Nutritional status
Neonatology~Newborns must adapt rapidly from placental support to independent breathing and feeding.~Prematurity affects temperature control, respiration, feeding and infection risk.|Neonatal jaundice must be interpreted by age in hours, gestation and risk factors.|Poor feeding, lethargy, respiratory difficulty or temperature instability can signal serious illness.~Why must newborn jaundice be interpreted by age in hours?~Risk depends strongly on postnatal timing~Birth>Physiological adaptation>Monitoring
Common infections & respiratory disease~Children may show nonspecific signs even with significant infection.~Respiratory distress is assessed through effort, rate, oxygenation and overall condition.|Dehydration assessment combines history, examination and severity signs.|A fever's seriousness depends on age and clinical context, not temperature alone.~Does temperature alone determine illness severity?~No~Infection>Child's response>Severity assessment
Pediatric organ-system disease~Congenital and acquired conditions can disrupt normal growth and function.~Congenital heart disease may produce cyanotic or noncyanotic patterns.|Nephrotic syndrome often presents with edema and substantial urinary protein loss.|Seizures require distinction from mimics and assessment of age, fever, metabolic causes and neurological findings.~Which finding commonly accompanies pediatric nephrotic syndrome?~Edema with substantial proteinuria~Underlying disorder>Organ effect>Growth or symptom pattern
Genetics, emergencies & adolescent health~Age-specific physiology changes both diagnosis and priorities.~Inherited conditions may follow Mendelian, chromosomal or complex patterns.|Pediatric emergencies require age-appropriate assessment and equipment.|Adolescent care includes confidential, developmentally appropriate communication within legal and safeguarding requirements.~Why is adult equipment not automatically suitable for children?~Size and physiology differ with age~Age and context>Tailored assessment>Appropriate care`},
{id:'ophthalmology',name:'Ophthalmology',phase:'Clinical',tagline:'Make vision and eye disease easier to see.',color:'#e5edf4',ink:'#466880',cover:'Bring the picture into focus.',flow:['Light','Retina','Vision'],scope:'Optics and refraction; conjunctiva and cornea; lens and cataract; glaucoma; uvea; retina; neuro-ophthalmology; ocular trauma; community ophthalmology',units:`
Optics, refraction & examination~The eye focuses light onto the retina, which converts it into neural signals.~Myopia focuses parallel rays in front of the retina; hyperopia focuses them behind it in an unaccommodated eye.|Visual acuity measures one part of vision; fields, pupils and ocular examination add other information.|Refractive error and ocular disease may coexist.~Where do parallel rays focus in uncorrected myopia?~In front of the retina~Light>Optical focus>Retinal signal
Conjunctiva & cornea~Surface disease can cause redness, irritation, pain or impaired vision.~Conjunctivitis and keratitis affect different tissues and can differ in severity.|Pain, photophobia or reduced vision with a red eye warrants prompt professional assessment.|The cornea must remain transparent and appropriately curved for clear vision.~Which transparent tissue forms the front optical surface?~Cornea~Surface injury>Inflammation>Visual disturbance
Lens & cataract~A cataract is clouding of the lens, making the optical path less clear.~The lens changes shape during accommodation to assist near focus.|Cataract commonly causes gradual visual impairment and glare, but other conditions may coexist.|Assessment establishes whether symptoms match the lens changes and evaluates the rest of the eye.~What is a cataract?~Opacity of the lens~Lens opacity>Light scattering>Visual impairment
Glaucoma & uveitis~Damage behind a red or apparently quiet eye may threaten vision.~Glaucoma is an optic neuropathy with characteristic structural and functional damage; pressure is an important risk factor.|A normal pressure reading does not rule out glaucoma.|Uveitis is inflammation of the uveal tract and may have infectious or immune-mediated causes.~Does a normal intraocular pressure exclude glaucoma?~No~Risk factors>Optic nerve damage>Field loss
Retina & systemic disease~The retina is neural tissue with a delicate blood supply.~Diabetes and hypertension may affect retinal vessels.|Retinal detachment separates neurosensory retina from its underlying support; sudden flashes, floaters or a curtain-like loss need urgent assessment.|Fundus findings must be related to the clinical history and visual function.~Which systemic disease commonly causes diabetic retinopathy?~Diabetes mellitus~Vascular injury>Retinal damage>Visual effect
Neuro-ophthalmology & trauma~Vision depends on intact pathways from the retina to the brain.~Optic nerve lesions and lesions farther along the visual pathway produce different field patterns.|Pupil responses and eye movements help localize neurological disorders.|Ocular trauma requires urgent assessment when serious; avoid assumptions based only on external appearance.~What helps localize a visual pathway lesion?~The visual field pattern~Retina>Optic pathways>Visual cortex`},
{id:'ent',name:'ENT',phase:'Clinical',tagline:'Connect hearing, balance, breathing and voice.',color:'#eee9df',ink:'#7d6b4d',cover:'Listen to the anatomy.',flow:['Sound','Signal','Hearing'],scope:'Ear anatomy and hearing; otitis; hearing loss and vestibular disorders; nose and paranasal sinuses; pharynx and tonsils; larynx; head and neck tumors; ENT emergencies',units:`
Hearing & ear examination~The outer and middle ear conduct sound; the inner ear converts it into electrical signals.~Conductive hearing loss affects sound transmission; sensorineural loss involves cochlear or neural pathways.|Otoscopy examines the canal and tympanic membrane.|Tuning-fork tests suggest a pattern, while audiometry quantifies hearing more precisely.~Which type of loss involves the cochlea or auditory nerve?~Sensorineural hearing loss~Sound>Mechanical vibration>Neural signal
Otitis & middle-ear disease~Infection or poor ventilation can change pressure and fluid in the middle ear.~The eustachian tube connects the middle ear to the nasopharynx.|Acute otitis media and otitis media with effusion are distinct conditions.|Cholesteatoma can erode local structures and requires specialist assessment.~Which tube ventilates the middle ear?~Eustachian tube~Ventilation problem>Fluid or infection>Hearing effect
Vertigo & vestibular disorders~Vertigo is a sense of movement when no matching movement is occurring.~The vestibular system integrates inner-ear, visual and proprioceptive inputs.|Peripheral and central causes may differ in associated features, but no single symptom is universally definitive.|New neurological signs with vertigo require urgent evaluation.~Which inner-ear system contributes to balance?~Vestibular system~Sensory input>Central integration>Balance
Nose & paranasal sinuses~The nose filters and conditions air, and sinus drainage depends on open pathways.~Rhinitis has allergic and nonallergic causes.|Sinus symptoms should be interpreted by duration, pattern and severity rather than color of discharge alone.|Epistaxis is nasal bleeding; cause and severity guide clinical assessment.~Does colored nasal discharge alone prove bacterial infection?~No~Mucosal swelling>Drainage change>Symptoms
Pharynx, tonsils & swallowing~The throat is a shared passage with protective mechanisms during swallowing.~Swallowing involves coordinated oral, pharyngeal and esophageal phases.|Tonsillitis, abscess and noninfectious causes can produce throat pain.|Dysphagia is difficulty swallowing; odynophagia is painful swallowing.~What does odynophagia mean?~Painful swallowing~Bolus formation>Pharyngeal transfer>Esophageal transit
Larynx, airway & head-neck disease~The larynx protects the airway and produces voice.~Vocal-fold vibration generates sound; nerve or structural changes may alter voice.|Persistent hoarseness needs assessment, especially with risk factors or other concerning symptoms.|Stridor suggests upper-airway narrowing and can represent an emergency.~What does stridor suggest?~Upper-airway narrowing~Airflow>Vocal-fold vibration>Voice`},
{id:'orthopedics',name:'Orthopedics',phase:'Clinical',tagline:'Build a framework for bones, joints and movement.',color:'#e7ecdf',ink:'#617245',cover:'Support. Move. Repair.',flow:['Bone','Joint','Movement'],scope:'Fractures and dislocations; healing and complications; musculoskeletal infection; metabolic bone disease; tumors; pediatric orthopedics; spine; arthritis; rehabilitation',units:`
Fractures & bone healing~A fracture disrupts bone continuity; healing restores mechanical strength over time.~Describe site, pattern, displacement and whether the fracture is open or closed.|Bone healing can occur through different pathways depending on stability and biological conditions.|Neurovascular examination is essential before and after interventions.~What makes a fracture open?~Communication between fracture and the external environment~Fracture>Repair tissue>Bone remodeling
Trauma complications & dislocations~An injury can damage vessels, nerves and soft tissues as well as bone.~A dislocation is loss of normal joint congruity.|Compartment syndrome involves raised pressure within a closed fascial space, threatening perfusion.|Severe pain and concerning examination findings require urgent evaluation; absent pulses are not required early.~What is threatened in compartment syndrome?~Tissue perfusion within a closed compartment~Swelling>Pressure rise>Ischemia
Bone & joint infection~Infection can affect bone or a joint and may cause rapid damage.~Osteomyelitis is bone infection; septic arthritis is infection within a joint.|Presentation varies by age, organism and route of infection.|A painful swollen joint with suspected infection requires urgent assessment.~What is septic arthritis?~Infection within a joint~Infection>Inflammation>Tissue destruction
Metabolic bone disease & tumors~Bone strength depends on quantity, quality and mineralization.~Osteoporosis reduces bone strength; osteomalacia involves defective mineralization.|Bone tumors are evaluated by age, site, imaging and histology where appropriate.|A radiographic pattern narrows a differential but is not always diagnostic alone.~Which disorder involves defective bone mineralization?~Osteomalacia~Bone process>Structural change>Fracture risk
Pediatric orthopedics & spine~Growing bones and spinal structures have unique patterns of injury and disease.~Growth-plate injuries can affect future growth and alignment.|Scoliosis is a three-dimensional spinal deformity, not simply poor posture.|Back pain with major neurological symptoms needs urgent evaluation.~Why are growth-plate injuries important?~They can affect future bone growth~Growth plate>Longitudinal growth>Alignment
Arthritis & rehabilitation~Joint symptoms arise from cartilage, synovium, bone or surrounding structures.~Osteoarthritis involves the whole joint and commonly has a mechanical symptom pattern.|Inflammatory arthritis often has prolonged stiffness and inflammatory findings.|Rehabilitation aims to restore function through individualized mobility, strength and participation goals.~What is a central goal of rehabilitation?~Restore function and participation~Impairment>Targeted rehabilitation>Function`},
{id:'dermatology',name:'Dermatology',phase:'Clinical',tagline:'Read the skin through patterns and mechanisms.',color:'#f4e8e2',ink:'#93654e',cover:'Every pattern tells a story.',flow:['Lesion','Pattern','Cause'],scope:'Lesion morphology; eczema and psoriasis; bacterial, viral and fungal infections; infestations; acne; pigment disorders; autoimmune and bullous disease; leprosy; STIs; skin tumors',units:`
Lesion morphology & examination~Describe what you see before naming a skin disease.~A macule is a flat color change; a papule is a small raised solid lesion; a vesicle contains fluid.|Distribution, border, scale and associated symptoms narrow the differential.|Different diseases can share a lesion type, so morphology alone may not establish diagnosis.~What is a macule?~A flat change in skin color~Lesion description>Distribution>Differential
Eczema & psoriasis~Inflammatory skin diseases often recur and have characteristic patterns.~Eczema commonly involves itch and an impaired skin barrier.|Psoriasis is an immune-mediated disease often producing well-defined scaly plaques.|Triggers, distribution and systemic associations help distinguish conditions.~Which symptom is especially common in eczema?~Itch~Barrier or immune change>Inflammation>Skin lesions
Infections & infestations~Skin infection reflects interaction between an organism, the barrier and host defenses.~Bacterial, fungal and viral infections need different diagnostic approaches.|Dermatophytes affect keratinized tissue such as skin, hair and nails.|Scabies is an infestation caused by mites and often causes intense itch.~What tissues do dermatophytes commonly affect?~Keratinized skin, hair and nails~Organism>Skin interaction>Lesion pattern
Acne, hair & pigment disorders~Follicles and pigment cells create distinct groups of skin conditions.~Acne involves follicular plugging, sebum, inflammation and microbial factors.|Vitiligo involves loss of functional melanocytes and depigmentation.|Hair loss is classified by pattern and whether scarring is present.~Which cells produce melanin?~Melanocytes~Cell or follicle change>Visible pattern>Assessment
Autoimmune, bullous & drug reactions~Immune injury can target different layers and components of the skin.~Blister location and immunopathology help distinguish bullous disorders.|Drug reactions range from mild eruptions to severe systemic disease.|Widespread blistering, mucosal involvement or systemic illness requires urgent assessment.~What helps distinguish immune blistering diseases?~Level of blister formation and immunopathology~Immune target>Tissue separation>Blister
Leprosy, STIs & skin tumors~Skin findings can signal nerve involvement, infection or abnormal growth.~Leprosy may affect skin and peripheral nerves; sensory examination is important.|STI assessment integrates exposure, symptoms, examination and appropriate testing without stigma.|Changing or suspicious lesions require professional assessment; appearance alone cannot reliably exclude malignancy.~Which additional system is commonly affected in leprosy?~Peripheral nerves~Clinical clue>Focused examination>Confirmation`},
{id:'psychiatry',name:'Psychiatry',phase:'Clinical',tagline:'Understand mental health with clarity and care.',color:'#ece8f2',ink:'#705c85',cover:'Mind, context and care.',flow:['Experience','Assessment','Support'],scope:'Psychiatric history and mental status; mood disorders; anxiety and trauma; psychosis; substance-use disorders; cognitive disorders; child psychiatry; personality; treatment principles and emergencies',units:`
Psychiatric assessment~A mental-health assessment considers experience, behavior, functioning and context.~The mental status examination describes current appearance, speech, mood, thought, perception and cognition.|Symptoms must be interpreted with duration, distress, functional effect and cultural context.|A diagnosis is not a judgment about character, and one symptom rarely establishes it.~What does the mental status examination primarily describe?~Current mental functioning~History>Current examination>Formulation
Mood disorders~Mood disorders affect emotional state, energy and everyday functioning over time.~Depressive episodes involve a constellation of symptoms with duration and impairment criteria.|Mania includes abnormal mood and increased activity or energy with associated symptoms and significant impact.|Bipolar and unipolar disorders differ in course and treatment implications.~Which episode is central to bipolar I disorder?~A manic episode~Symptoms over time>Episode pattern>Diagnostic assessment
Anxiety, OCD & trauma~Fear, intrusive thoughts and trauma responses become clinical concerns when patterns cause significant distress or impairment.~Panic attacks are intense surges of fear or discomfort and can occur in several disorders.|Obsessions are intrusive unwanted thoughts or urges; compulsions are repetitive acts performed in response.|Trauma-related diagnoses depend on exposure and specific symptom patterns, not distress alone.~What is a compulsion?~A repetitive act performed in response to an obsession or rule~Trigger>Distress>Behavioral response
Psychosis~Psychosis can affect interpretation of reality and has psychiatric, medical and substance-related causes.~Hallucinations are perception-like experiences without a corresponding external stimulus.|Delusions are fixed beliefs not readily changed by contrary evidence, interpreted in cultural context.|Assessment considers onset, medical causes, substances, function and safety.~What is a hallucination?~A perception-like experience without a corresponding external stimulus~Presentation>Cause assessment>Support and treatment
Substance use & cognitive disorders~Substances and brain disorders can affect behavior, attention and memory.~Dependence-related features can include impaired control and continued use despite harm.|Delirium is an acute, fluctuating disturbance of attention and awareness caused by an underlying physiological process.|Dementia involves acquired cognitive decline affecting independence; delirium may coexist.~Which condition features acute fluctuating inattention?~Delirium~Underlying cause>Cognitive change>Functional effect
Child psychiatry & treatment principles~Development and family context shape how symptoms appear and how support is delivered.~Neurodevelopmental assessment examines development, functioning and context over time.|Psychological, social and medication-based interventions may be combined according to the condition and patient goals.|Psychiatric emergencies require timely professional assessment; treatment choices are individualized.~Why does developmental history matter in child psychiatry?~Symptoms must be understood relative to developmental stage~Developmental context>Assessment>Individualized support`},
{id:'radiology',name:'Radiology',phase:'Clinical',tagline:'Understand what each scan can—and cannot—show.',color:'#e5e9ed',ink:'#4d6674',cover:'Look beyond the image.',flow:['Question','Modality','Finding'],scope:'Imaging principles; radiation safety; X-ray, ultrasound, CT and MRI; chest and abdominal imaging; neuroimaging; musculoskeletal imaging; contrast; interventional radiology',units:`
Imaging physics & modality choice~An imaging test is selected to answer a particular clinical question.~X-ray and CT use ionizing radiation; ultrasound uses sound waves; MRI uses magnetic fields and radiofrequency signals.|No modality is best for every tissue or question.|Image quality, availability, contraindications and patient factors influence selection.~Which modality uses sound waves?~Ultrasound~Clinical question>Imaging choice>Interpretation
Chest imaging~A systematic approach reduces missed findings on a chest image.~Check identity, projection and image quality before interpreting anatomy.|Evaluate lungs, pleura, heart, mediastinum, bones and soft tissues in a consistent order.|An opacity is a description, not a diagnosis; correlate with clinical context.~What should be checked before interpreting a chest radiograph?~Identity, projection and image quality~Quality check>Systematic review>Clinical correlation
Abdominal imaging~Different techniques reveal gas, fluid, organs and vessels differently.~Ultrasound is useful for many biliary, pelvic and pregnancy-related questions.|CT provides cross-sectional information and may use contrast depending on the question.|A normal test does not exclude every cause of abdominal symptoms.~What does cross-sectional imaging provide?~Internal anatomy in sectional views~Symptom>Targeted modality>Anatomic finding
Neuroimaging~Imaging helps distinguish causes of neurological symptoms, but timing matters.~Noncontrast CT is often used rapidly to assess acute intracranial hemorrhage.|MRI offers multiple sequences with different tissue sensitivities.|Early ischemic change may be subtle; imaging must be interpreted with onset and examination.~Which scan is commonly used rapidly for acute intracranial hemorrhage?~Noncontrast CT~Neurological finding>Appropriate imaging>Localization
Musculoskeletal imaging~Read alignment, bone and surrounding tissue systematically.~Fractures may require more than one view and may occasionally be occult initially.|MRI is useful for many soft-tissue and marrow questions.|Imaging findings should match the site and nature of the symptoms.~Why are multiple radiographic views often needed?~A fracture or displacement may be hidden in one projection~Alignment>Bone detail>Soft tissues
Radiation, contrast & interventions~Useful imaging balances information against risks and practical limitations.~Justification and dose optimization are core principles of radiation protection.|Contrast agents differ by modality; risks depend on agent, patient and route.|Image guidance can support diagnostic sampling and therapeutic procedures.~What are two core radiation-protection principles?~Justification and dose optimization~Benefit assessment>Risk reduction>Useful examination`},
{id:'anesthesia',name:'Anesthesiology',phase:'Clinical',tagline:'Connect airway, physiology and safe procedural care.',color:'#e2eeea',ink:'#3d7465',cover:'Physiology in real time.',flow:['Assess','Monitor','Support'],scope:'Preanesthetic assessment; airway; general, regional and local anesthesia; monitoring; ventilation; fluids; pain; resuscitation; intensive care and complications',units:`
Preanesthetic assessment~Anesthesia planning depends on the patient, procedure and expected physiological stresses.~Review medical history, medicines, previous anesthesia and airway features.|Risk classification supports communication but cannot replace individualized assessment.|Fasting and medication instructions must follow current professional guidance for the particular patient and procedure.~What determines an anesthesia plan?~Patient factors, procedure and physiological risk~Assessment>Risk planning>Preparation
Airway & ventilation~Oxygen delivery requires a patent airway, ventilation, gas exchange and circulation.~Ventilation moves air; oxygenation adds oxygen to blood; the two are related but distinct.|Airway devices and techniques require trained operators and appropriate rescue planning.|Capnography provides information about exhaled carbon dioxide and ventilation.~What does capnography monitor?~Exhaled carbon dioxide~Airway patency>Ventilation>Gas exchange
General anesthesia~General anesthesia combines components such as unconsciousness, analgesia and immobility.~Different drug classes provide different components rather than one identical effect.|Neuromuscular blockers do not themselves provide unconsciousness or pain relief.|Continuous physiological monitoring helps detect adverse changes promptly.~Do neuromuscular blockers provide analgesia by themselves?~No~Drug effects>Physiological monitoring>Recovery
Local & regional anesthesia~Nerve conduction can be interrupted in a defined area while other functions are preserved.~Local anesthetics block voltage-gated sodium channels.|Regional techniques target nerves, plexuses or neuraxial spaces.|Technique, dose, anatomy and monitoring influence safety; these procedures require supervised clinical training.~Which channels are blocked by local anesthetics?~Voltage-gated sodium channels~Sodium-channel block>Conduction interruption>Regional loss of sensation
Monitoring, fluids & critical care~Critical care tracks organ function and treats causes of physiological instability.~Pulse oximetry estimates arterial oxygen saturation but does not directly measure ventilation.|Fluid decisions depend on hemodynamics, ongoing losses, organ function and response.|Trends and the whole clinical picture matter more than isolated monitor values.~Does pulse oximetry directly measure ventilation?~No~Measurement>Interpretation>Reassessment
Pain & resuscitation principles~Pain care and resuscitation depend on matching action to mechanism and urgency.~Multimodal analgesia combines approaches that act through different mechanisms.|Resuscitation uses structured assessment, timely help and guideline-based interventions.|Current algorithms and practical skills require accredited training; written notes are not procedural certification.~What is multimodal analgesia?~Combining pain treatments with different mechanisms~Assessment>Coordinated intervention>Reassessment`}
];
const FOUNDATION_RAW=`
The body's levels of organization~Start with scale: tiny cells work together to make tissues, organs and systems.~A cell is a basic living unit.|Similar specialized cells and surrounding material form tissues.|Organs combine tissues; organ systems coordinate larger tasks.~What is a basic living unit?~A cell~Cell>Tissue>Organ
The language of medicine~Medical words become easier when you split them into meaningful pieces.~Cardio refers to the heart; neuro refers to nerves.|The suffix -itis generally means inflammation.|A term describes a concept, not always its cause: hepatitis means liver inflammation, not necessarily a viral infection.~What does the suffix -itis generally mean?~Inflammation~Word part>Meaning>Clinical term
Directions, planes & body maps~Doctors use a shared coordinate system to describe locations precisely.~Anterior means toward the front; posterior means toward the back.|Superior means above; inferior means below.|A sagittal plane divides left and right portions; a transverse plane divides upper and lower portions.~What does medial mean?~Toward the midline~Anatomical position>Shared directions>Precise location
Cells, membranes & transport~A cell membrane is a selective boundary, not a solid wall.~Water and dissolved substances move by different transport mechanisms.|Diffusion follows a concentration gradient.|Osmosis describes water movement across a selectively permeable membrane.~What is osmosis?~Water movement across a selectively permeable membrane~Concentration difference>Membrane transport>New balance
Homeostasis in everyday life~Sweating when warm is one example of a response that limits a disturbance.~Sensors detect change in a controlled variable.|A control system coordinates a response.|Negative feedback reduces the original disturbance rather than amplifying it.~Which feedback type reduces a disturbance?~Negative feedback~Disturbance>Detection>Correction
Blood, oxygen & circulation~Blood transports oxygen and nutrients while carrying away waste.~The right heart pumps through the lungs; the left pumps through the body.|Arteries carry blood away from the heart; veins return it, regardless of oxygen content.|Most blood oxygen is carried by hemoglobin in red cells.~Are all arteries oxygen-rich?~No, pulmonary arteries carry oxygen-poor blood~Body>Right heart>Lungs
Breathing versus gas exchange~Moving air and moving gases into blood are separate steps.~The diaphragm helps expand the chest during inspiration.|Oxygen diffuses from alveoli into pulmonary blood under normal conditions.|Carbon dioxide travels in the opposite direction for exhalation.~What is ventilation?~Movement of air into and out of the lungs~Air movement>Alveoli>Gas diffusion
Food, digestion & energy~Digestion breaks food into absorbable building blocks.~Proteins supply amino acids; carbohydrates supply simple sugars; fats supply fatty acids and other components.|Enzymes catalyze digestion at different sites.|Absorbed nutrients can be used for energy, growth or storage.~What are proteins broken into during digestion?~Amino acids and small peptides~Food>Digestion>Absorption
Kidneys & fluid balance~Kidneys filter blood and adjust what stays in the body.~Useful substances are often reabsorbed after filtration.|Waste and excess substances leave in urine.|Kidneys also participate in blood-pressure regulation, red-cell signaling and acid–base balance.~Is everything filtered by the kidney lost in urine?~No, much is reabsorbed~Filtration>Reabsorption>Excretion
Nerves & hormones~The body uses fast electrical messages and chemical messengers to coordinate organs.~Neurons communicate through electrical changes and chemical transmitters.|Hormones travel to cells with appropriate receptors.|A receptor is a molecular structure that recognizes a signal.~Why do only certain cells respond to a hormone?~They have the appropriate receptor~Signal>Receptor>Response
Germs, immunity & vaccines~Microbes are not all harmful; the immune system distinguishes and responds to threats.~Barriers such as skin provide first-line protection.|Innate and adaptive immunity work together.|Vaccines train protective responses; effectiveness and schedules depend on the vaccine and disease.~What is immune memory?~A learned capacity to respond to a previously encountered antigen~Exposure>Immune learning>Later response
Symptoms, signs & investigations~A symptom is experienced by the patient; a sign is observed or measured.~Pain is a symptom; a measured fever is a sign.|An investigation tests a question raised by the clinical assessment.|No test is perfect, so results must be interpreted in context.~How does a sign differ from a symptom?~A sign is observed or measured~History>Examination>Targeted test
Risk, probability & evidence~Medicine makes decisions under uncertainty using evidence and context.~A risk factor changes probability but does not guarantee an outcome.|Association does not automatically imply causation.|Absolute risk and relative risk convey different information; ask for the baseline risk.~Does a risk factor guarantee disease?~No~Baseline risk>New information>Updated probability
How to study a medical concept~Move from understanding to retrieval, then revisit the material after a delay.~Explain a mechanism in everyday words before memorizing terminology.|Close the lesson and retrieve the answer without looking.|Return to missed concepts and connect them with a diagram or clinical example.~What is active recall?~Retrieving information without looking at the answer~Understand>Retrieve>Revisit`;
function parseUnits(raw,subject){return raw.trim().split('\n').map((line,i)=>{const [title,simple,detail,q,a,flow]=line.trim().split('~');return{id:`${subject}-${i}`,subject,title,simple,detail:detail.split('|'),q,a,flow:flow.split('>')};});}
SUBJECTS.forEach(s=>s.lessons=parseUnits(s.units,s.id));
const FOUNDATION={id:'foundation',name:'Medicine from zero',phase:'Foundation',tagline:'A friendly first step into medical science.',color:'#edf2df',scope:'Medical vocabulary, anatomy basics, cells, feedback, circulation, respiration, digestion, renal function, signaling, immunity, clinical language, evidence and study skills',lessons:parseUnits(FOUNDATION_RAW,'foundation')};
const ALL_SUBJECTS=[FOUNDATION,...SUBJECTS];
const ALL_LESSONS=ALL_SUBJECTS.flatMap(s=>s.lessons);
const DAYS=[];
FOUNDATION.lessons.forEach(l=>DAYS.push({type:'learn',subject:'foundation',title:l.title,lessons:[l.id]}));
SUBJECTS.forEach(s=>{s.lessons.forEach(l=>DAYS.push({type:'learn',subject:s.id,title:l.title,lessons:[l.id]}));DAYS.push({type:'map',subject:s.id,title:`Connect the dots: ${s.name}`,lessons:s.lessons.map(l=>l.id)});DAYS.push({type:'review',subject:s.id,title:`Active recall: ${s.name}`,lessons:s.lessons.map(l=>l.id)});});
const REVISION_GROUPS=[['anatomy','physiology'],['biochemistry','pathology'],['pharmacology','microbiology'],['forensic','community'],['medicine','radiology'],['surgery','anesthesia'],['obgyn','pediatrics'],['ophthalmology','ent'],['orthopedics','dermatology'],['psychiatry','medicine'],['physiology','pharmacology'],['pathology','surgery'],['microbiology','community'],SUBJECTS.map(s=>s.id)];
REVISION_GROUPS.forEach((ids,i)=>DAYS.push({type:'revision',subject:'revision',title:i===13?'Final recall & next-cycle planning':`Integrated revision ${i+1}: ${ids.map(id=>SUBJECTS.find(s=>s.id===id).name).join(' + ')}`,lessons:ids.flatMap(id=>SUBJECTS.find(s=>s.id===id).lessons.map(l=>l.id))}));
DAYS.forEach((d,i)=>d.day=i+1);
